include  <p>int main() {     int arr[] = {1, 2, 3, 4, 5};   // Български: Декларираме масив от цели числа                                    // English: Declare an array of integers     int *ptr = arr;               // Български: Указателят сочи към първия елемент на масива                                    // English: Pointer points to the first element of the array</p> <pre><code>for (int i = 0; i &lt; 5; i++) {
    std::cout &lt;&lt; "Value at index " &lt;&lt; i &lt;&lt; ": " &lt;&lt; *(ptr + i) &lt;&lt; std::endl; 
    // Български: Извеждаме стойността на елемента на текущия индекс
    // English: Output the value of the element at the current index
}

return 0;
</code></pre> <p>}</p>

include  <p>int main() {     int *dynamicVar = new int(10); // Български: Заделяме динамично памет за цяло число и го инициализираме със стойност 10                                    // English: Dynamically allocate memory for an integer and initialize it to 10</p> <pre><code>std::cout &lt;&lt; "Dynamic value: " &lt;&lt; *dynamicVar &lt;&lt; std::endl; // Български: Извеждаме стойността на динамичното число
                                                            // English: Output the value of the dynamically allocated integer

delete dynamicVar; // Български: Освобождаваме паметта
                   // English: Free the allocated memory

return 0;
</code></pre> <p>}</p>

include  <p>void printMessage() {     std::cout &lt;&lt; "Hello from a function!" &lt;&lt; std::endl;      // Български: Функцията извежда съобщение     // English: The function prints a message }</p> <p>int main() {     void (*funcPtr)() = printMessage; // Български: Указателят funcPtr сочи към функцията printMessage                                       // English: Pointer funcPtr points to the function printMessage</p> <pre><code>funcPtr(); // Български: Извикваме функцията чрез указателя
           // English: Call the function via the pointer

return 0;
</code></pre> <p>}</p>

include  <p>int main() {     int x = 100;                    // Български: Декларираме променлива x със стойност 100                                     // English: Declare variable x with value 100     int ptr = &amp;x;                  // Български: Указател ptr сочи към x                                     // English: Pointer ptr points to x     int *doublePtr = &amp;ptr;         // Български: doublePtr сочи към ptr                                     // English: doublePtr points to ptr</p> <pre><code>std::cout &lt;&lt; "Value of x: " &lt;&lt; **doublePtr &lt;&lt; std::endl; 
// Български: Извеждаме стойността на x чрез указател към указател
// English: Output the value of x via pointer-to-pointer

return 0;
</code></pre> <p>}</p>
